    sentences: [
      { start: 4.8, en: "Jim wanted to fly a kite.", ipa: "/dʒɪm ˈwɒntɪd tuː flaɪ ə kaɪt/", vi: "Jim rất muốn đi thả diều." },
      { start: 8.5, en: "His father asked him, 'What do we need to fly a kite?'", ipa: "/hɪz ˈfɑːðər ɑːskt hɪm wɒt duː wiː niːd tuː flaɪ ə kaɪt/", vi: "Bố hỏi cậu: 'Theo con chúng ta cần gì để thả diều nào?'" },
      { start: 16.5, en: "A kite!' said Jim.", ipa: "/ə kaɪt sɛd dʒɪm/", vi: "'Một chiếc diều ạ!' Jim đáp." },
      { start: 20.0, en: "Of course. What else?' his father asked again.", ipa: "/v kɔːrs. wɒt ɛls? hɪz ˈfɑːðər ɑːskt əˈɡɛn/", vi: "'Đương nhiên rồi. Còn gì nữa không?' bố lại hỏi tiếp." },
      { start: 26.5, en: "Jim didn't know.", ipa: "/dʒɪm ˈdɪdnt noʊ/", vi: "Jim ngớ người không biết." },
      { start: 29.5, en: "We need a lot of space to run and let the kite fly,' his father said.", ipa: "/wiː niːd ə lɒt əv speɪs tuː rʌn ænd lɛt ðə kaɪt flaɪ hɪz ˈfɑːðər sɛd/", vi: "'Chúng ta cần khoảng không gian rộng để chạy thả diều,' bố giải thích." },
      { start: 38.0, en: "That's not all. We need something else.'", ipa: "/ðæts nɒt ɔːl. wiː niːd ˈsʌmθɪŋ ɛls/", vi: "'Vẫn chưa hết đâu. Ta còn cần thêm một thứ nữa.'" },
      { start: 43.5, en: "What is it then?' asked Jim.", ipa: "/wɒt ɪz ɪt ðɛn? ɑːsks dʒɪm/", vi: "'Thế đó là gì ạ?' Jim tò mò hỏi." },
      { start: 47.5, en: "We need wind! Lots of wind,' his father said loudly.", ipa: "/wiː niːd wɪnd! lɒts əv wɪnd hɪz ˈfɑːðər sɛd ˈlaʊdli/", vi: "'Đó chính là gió! Thật nhiều gió,' bố cười lớn nói." },
      { start: 56.5, en: "Come on, wind. Blow!", ipa: "/kʌm ɒn wɪnd. bloʊ!/", vi: "Nào gió ơi, hãy thổi mạnh lên nào!" }
    ]
